package com.bank.grpc.tracing;

import io.grpc.*;
import io.opentelemetry.api.OpenTelemetry;
import io.opentelemetry.context.Context;
import io.opentelemetry.context.propagation.TextMapSetter;
import java.util.logging.Logger;

// CLIENT side: INJECT the current trace context into outgoing gRPC metadata.
public class TracingClientInterceptor implements ClientInterceptor {
    private static final Logger log = Logger.getLogger(TracingClientInterceptor.class.getName());
    private final OpenTelemetry otel;
    public TracingClientInterceptor(OpenTelemetry otel) { this.otel = otel; }

    // Writes W3C traceparent into Metadata.
    private static final TextMapSetter<Metadata> SETTER = (carrier, key, value) ->
        carrier.put(Metadata.Key.of(key, Metadata.ASCII_STRING_MARSHALLER), value);

    @Override
    public <Req, Resp> ClientCall<Req, Resp> interceptCall(
            MethodDescriptor<Req, Resp> method, CallOptions opts, Channel next) {
        return new ForwardingClientCall.SimpleForwardingClientCall<>(next.newCall(method, opts)) {
            @Override public void start(Listener<Resp> responseListener, Metadata headers) {
                // inject active context (trace id + span id) into metadata
                otel.getPropagators().getTextMapPropagator()
                    .inject(Context.current(), headers, SETTER);
                log.fine(() -> "Injected trace context into " + method.getFullMethodName());
                super.start(responseListener, headers);
            }
        };
    }
}
