package com.bank.grpc.tracing;

import io.grpc.*;
import io.opentelemetry.api.OpenTelemetry;
import io.opentelemetry.api.trace.*;
import io.opentelemetry.context.Context;
import io.opentelemetry.context.propagation.TextMapGetter;
import java.util.logging.Logger;

// SERVER side: EXTRACT trace context from incoming metadata, start a CHILD span.
public class TracingServerInterceptor implements ServerInterceptor {
    private static final Logger log = Logger.getLogger(TracingServerInterceptor.class.getName());
    private final OpenTelemetry otel;
    private final Tracer tracer;
    public TracingServerInterceptor(OpenTelemetry otel, Tracer tracer) {
        this.otel = otel; this.tracer = tracer;
    }

    private static final TextMapGetter<Metadata> GETTER = new TextMapGetter<>() {
        @Override public Iterable<String> keys(Metadata c) { return c.keys(); }
        @Override public String get(Metadata c, String key) {
            var mk = Metadata.Key.of(key, Metadata.ASCII_STRING_MARSHALLER);
            return c.containsKey(mk) ? c.get(mk) : null;
        }
    };

    @Override
    public <Req, Resp> ServerCall.Listener<Req> interceptCall(
            ServerCall<Req, Resp> call, Metadata headers, ServerCallHandler<Req, Resp> next) {
        // extract parent context from metadata → start child server span
        Context parent = otel.getPropagators().getTextMapPropagator()
            .extract(Context.current(), headers, GETTER);
        Span span = tracer.spanBuilder(call.getMethodDescriptor().getFullMethodName())
            .setParent(parent).setSpanKind(SpanKind.SERVER).startSpan();
        log.info(() -> "Server span started traceId=" + span.getSpanContext().getTraceId());

        try (var scope = span.makeCurrent()) {
            return next.startCall(call, headers);
        } finally {
            span.end();
        }
    }
}
